mapper.select:
/* selectMasterMdPpPropList */ SELECT A.PP_NO, A.USER_DEPT, A.REQ_USER_ID, A.USER_NAME, A.ADD_DATE, A.PP_SUBJECT, A.STATUS, A.STATUS_TEXT, A.PP_ARPS_ID1, DECODE(A.PP_POINT1, '0', '미평가', A.PP_POINT1) AS PP_POINT1, A.PP_ARPS_ID2, DECODE(A.PP_POINT2, '0', '미평가', A.PP_POINT2) AS PP_POINT2, A.PP_ARPS_ID3, DECODE(A.PP_POINT3, '0', '미평가', A.PP_POINT3) AS PP_POINT3, A.PP_ARPS_ID4, DECODE(A.PP_POINT4, '0', '미평가', A.PP_POINT4) AS PP_POINT4, A.PP_ARPS_ID5, DECODE(A.PP_POINT5, '0', '미평가', A.PP_POINT5) AS PP_POINT5, A.PP_ARPS_ID6, A.PP_POINT6, DECODE(A.PP_POINT6, 'R', '불채택', '1', '1등급', '2', '2등급', '3', '3등급', '4', '4등급', '5', '5등급', '' ) AS PP_POINT6_TEXT, A.EXC_DEPT, A.EXC_DEPT_NAME, A.CHK_ARPS_ID, A.MODIFY_YN FROM ( SELECT PP_NO, USER_DEPT, REQ_USER_ID, USER_NAME, ADD_DATE, PP_SUBJECT, STATUS, STATUS_TEXT, MAX(PP_ARPS_ID1) AS PP_ARPS_ID1, MAX(DECODE(CHK_ARPS_ID, '', '*', PP_POINT1)) AS PP_POINT1, MAX(PP_ARPS_ID2) AS PP_ARPS_ID2, MAX(DECODE(CHK_ARPS_ID, '', '*', PP_POINT2)) AS PP_POINT2, MAX(PP_ARPS_ID3) AS PP_ARPS_ID3, MAX(DECODE(CHK_ARPS_ID, '', '*', PP_POINT3)) AS PP_POINT3, MAX(PP_ARPS_ID4) AS PP_ARPS_ID4, MAX(DECODE(CHK_ARPS_ID, '', '*', PP_POINT4)) AS PP_POINT4, MAX(PP_ARPS_ID5) AS PP_ARPS_ID5, MAX(DECODE(CHK_ARPS_ID, '', '*', PP_POINT5)) AS PP_POINT5, MAX(PP_ARPS_ID6) AS PP_ARPS_ID6, MAX(CASE WHEN STATUS = 'R' THEN 'R' WHEN PP_POINT6 >= 90 THEN '1' WHEN PP_POINT6 >= 70 THEN '2' WHEN PP_POINT6 >= 50 THEN '3' WHEN PP_POINT6 >= 35 THEN '4' WHEN PP_POINT6 > 0 THEN '5' ELSE '' END ) AS PP_POINT6, MAX(EXC_DEPT) AS EXC_DEPT, MAX(EXC_DEPT_NAME) AS EXC_DEPT_NAME, MAX(CHK_ARPS_ID) AS CHK_ARPS_ID, CASE STATUS WHEN 'C' THEN 'N' WHEN 'D' THEN 'N' WHEN 'R' THEN 'N' ELSE 'Y' END AS MODIFY_YN FROM ( SELECT HD.PP_NO AS PP_NO, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = U.COM_CODE AND CODE = U.DEPARTMENT) AS USER_DEPT, HD.PP_REQ_USER_ID AS REQ_USER_ID, U.USER_NAME_LOC AS USER_NAME, TO_CHAR(HD.ADD_DATE, 'YYYY/MM/DD HH24:MI') AS ADD_DATE, HD.PP_SUBJECT AS PP_SUBJECT, HD.STATUS, DECODE(HD.STATUS, 'G', '제안요청', 'P', '제안평가', 'C', '등급확정', 'D', '삭제', 'R', '불채택') AS STATUS_TEXT, DECODE(DT.PP_SEQ, '000001', PP_ARPS_ID, '') AS PP_ARPS_ID1, DECODE(DT.PP_SEQ, '000001', DECODE(DT.STATUS, 'R', '불채택', DT.PP_ATTB_P1 + DT.PP_ATTB_P2 + DT.PP_ATTB_P3 + DT.PP_ATTB_P4 + DT.PP_ATTB_P5), 0) AS PP_POINT1, DECODE(DT.PP_SEQ, '000002', PP_ARPS_ID, '') AS PP_ARPS_ID2, DECODE(DT.PP_SEQ, '000002', DECODE(DT.STATUS, 'R', '불채택', DT.PP_ATTB_P1 + DT.PP_ATTB_P2 + DT.PP_ATTB_P3 + DT.PP_ATTB_P4 + DT.PP_ATTB_P5), 0) AS PP_POINT2, DECODE(DT.PP_SEQ, '000003', PP_ARPS_ID, '') AS PP_ARPS_ID3, DECODE(DT.PP_SEQ, '000003', DECODE(DT.STATUS, 'R', '불채택', DT.PP_ATTB_P1 + DT.PP_ATTB_P2 + DT.PP_ATTB_P3 + DT.PP_ATTB_P4 + DT.PP_ATTB_P5), 0) AS PP_POINT3, DECODE(DT.PP_SEQ, '000004', PP_ARPS_ID, '') AS PP_ARPS_ID4, DECODE(DT.PP_SEQ, '000004', DECODE(DT.STATUS, 'R', '불채택', DT.PP_ATTB_P1 + DT.PP_ATTB_P2 + DT.PP_ATTB_P3 + DT.PP_ATTB_P4 + DT.PP_ATTB_P5), 0) AS PP_POINT4, DECODE(DT.PP_SEQ, '000005', PP_ARPS_ID, '') AS PP_ARPS_ID5, DECODE(DT.PP_SEQ, '000005', DECODE(DT.STATUS, 'R', '불채택', DT.PP_ATTB_P1 + DT.PP_ATTB_P2 + DT.PP_ATTB_P3 + DT.PP_ATTB_P4 + DT.PP_ATTB_P5), 0) AS PP_POINT5, DECODE(DT.PP_SEQ, '000006', PP_ARPS_ID, '') AS PP_ARPS_ID6, DECODE(DT.PP_SEQ, '000006', DECODE(DT.STATUS, 'R', '불채택', DT.PP_ATTB_P1 + DT.PP_ATTB_P2 + DT.PP_ATTB_P3 + DT.PP_ATTB_P4 + DT.PP_ATTB_P5), 0) AS PP_POINT6, DT.PP_EXC_DEPT AS EXC_DEPT, (SELECT NVL(TEXT1, '') FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = U.COM_CODE AND CODE = DT.PP_EXC_DEPT AND FLAG = 'Y') AS EXC_DEPT_NAME, ( SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M148' AND FLAG = 'Y' AND TEXT2 = #{st_user_id} ) AS CHK_ARPS_ID, DT.PP_R_REMARK FROM KEPAPPHD HD, KEPAPPDT DT, ICOMLUSR U WHERE 1=1 AND HD.PP_NO = DT.PP_NO AND HD.PP_REQ_USER_ID = U.USER_ID AND TO_CHAR(HD.ADD_DATE, 'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date} AND HD.PP_TYPE = #{st_pp_type}
AND HD.PP_REQ_USER_ID = #{st_kep_user_id}
AND HD.PP_NO LIKE #{st_pp_no_f} || '%' AND (HD.PP_SUBJECT LIKE '%' || #{st_remark} || '%' OR HD.PP_REMARK LIKE '%' || #{st_remark} || '%')
AND HD.STATUS = #{st_status}
) GROUP BY PP_NO, USER_DEPT, REQ_USER_ID, USER_NAME, ADD_DATE, PP_SUBJECT, STATUS, STATUS_TEXT ) A WHERE 1=1
AND A.PP_POINT6 = #{st_grade}
AND A.EXC_DEPT = #{st_exec_dept}
ORDER BY PP_NO DESC


/* selectMasterMdPpPropRejectPop */
SELECT	PP_R_REMARK
FROM	KEPAPPDT					
WHERE	PP_NO = #{st_pp_no}
AND		PP_SEQ = #{st_pp_seq}

mapper.update:

/* updateMasterMdPpPropArpsStatus */
UPDATE	KEPAPPHD
SET		STATUS = DECODE((SELECT STATUS FROM KEPAPPDT WHERE PP_NO = #{pp_no} AND PP_SEQ = '000006'), 'P', 'C', 'R', 'R', 'P'),
			CHANGE_DATE = SYSDATE,
			CHANGE_USER_ID = #{user_id}
WHERE	PP_NO = #{pp_no}
